-- ───────────────── 20261126090000_staff_rbac_tasks.sql ─────────────────
-- ─────────────────────────────────────────────────────────────────────────────
-- Staff roles (RBAC), classes, attendance and task management.
--
--   staff_profiles   per staff account: kind TEACHER | ADVISOR | MANAGER + campus (null = all campuses).
--                    A staff account WITHOUT a profile keeps today's full access (treated as MANAGER), so
--                    nothing breaks until the admin assigns roles. Admins (app_metadata.role = admin) see all.
--   classes / class_members   a teacher's classes and the enrollments in them.
--   attendance_logs  check-ins per class, student and day (QR scan or manual).
--   students.qr_token  unguessable code on the child's check-in QR (parents see it in the portal).
--   staff_tasks      advisor / teacher to-dos; created by admins or automatically (new lead → campus advisor,
--                    approved make-up request → class teacher, T+14 advisor call → advisor).
--
-- Visibility (RLS + guards on the mutating functions):
--   ADMIN / MANAGER  everything
--   ADVISOR          leads assigned to them or at their campus; enrollments / students at their campus
--   TEACHER          trial leads at their campus; enrollments / students / reports only in THEIR classes
-- ─────────────────────────────────────────────────────────────────────────────

create table public.staff_profiles (
  user_id          uuid primary key references auth.users (id) on delete cascade,
  kind             text not null default 'TEACHER' check (kind in ('TEACHER', 'ADVISOR', 'MANAGER')),
  campus_location  text references public.branches (code) on update cascade,
  display_name     text check (display_name is null or char_length(btrim(display_name)) between 2 and 60),
  phone            text check (phone is null or phone ~ '^0[35789][0-9]{8}$'),
  updated_by       uuid references auth.users (id) on delete set null,
  updated_at       timestamptz not null default now()
);

create table public.classes (
  id               uuid primary key default gen_random_uuid(),
  name             text not null check (char_length(btrim(name)) between 2 and 60),
  course_code      text not null references public.categories (code) on update cascade,
  level            smallint not null default 1 check (level between 1 and 5),
  campus_location  text not null references public.branches (code) on update cascade,
  teacher_id       uuid references auth.users (id) on delete set null,
  -- [{"d": 2..8, "start": "17:30", "end": "19:00"}] — same shape as enrollments.schedule
  schedule         jsonb not null default '[]' check (jsonb_typeof(schedule) = 'array'),
  is_active        boolean not null default true,
  created_by       uuid references auth.users (id) on delete set null,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);
create index classes_teacher_idx on public.classes (teacher_id) where is_active;
create trigger classes_set_updated_at before update on public.classes for each row execute function public.set_updated_at();

create table public.class_members (
  class_id       uuid not null references public.classes (id) on delete cascade,
  enrollment_id  uuid not null references public.enrollments (id) on delete cascade,
  created_at     timestamptz not null default now(),
  primary key (class_id, enrollment_id)
);
create index class_members_enrollment_idx on public.class_members (enrollment_id);

alter table public.students
  add column if not exists qr_token text unique default upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 20));
update public.students set qr_token = upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 20)) where qr_token is null;
alter table public.students alter column qr_token set not null;

create table public.attendance_logs (
  id             uuid primary key default gen_random_uuid(),
  student_id     uuid not null references public.students (id) on delete cascade,
  class_id       uuid not null references public.classes (id) on delete cascade,
  enrollment_id  uuid references public.enrollments (id) on delete set null,
  session_date   date not null,
  scanned_by     uuid references auth.users (id) on delete set null,
  check_in_time  timestamptz not null default now(),
  status         text not null check (status in ('PRESENT', 'LATE', 'ABSENT', 'EXCUSED')),
  method         text not null default 'MANUAL' check (method in ('QR', 'MANUAL')),
  unique (class_id, student_id, session_date)
);
create index attendance_logs_student_idx on public.attendance_logs (student_id, session_date desc);

alter table public.daily_reports
  add column if not exists class_id uuid references public.classes (id) on delete set null,
  add column if not exists tags text[] not null default '{}' check (cardinality(tags) <= 8);

alter table public.leads add column if not exists assigned_advisor uuid references auth.users (id) on delete set null;

create table public.staff_tasks (
  id            uuid primary key default gen_random_uuid(),
  assigned_to   uuid not null references auth.users (id) on delete cascade,
  assigned_by   uuid references auth.users (id) on delete set null,   -- null = created automatically
  title         text not null check (char_length(btrim(title)) between 3 and 120),
  description   text check (description is null or char_length(description) <= 1000),
  target_type   text not null default 'OTHER' check (target_type in ('LEAD_FOLLOWUP', 'MAKEUP_CLASS', 'HOMEWORK_GRADE', 'OTHER')),
  target_id     uuid,
  due_date      timestamptz not null,
  priority      smallint not null default 2 check (priority between 1 and 3),   -- 1 = cao
  status        text not null default 'PENDING' check (status in ('PENDING', 'IN_PROGRESS', 'COMPLETED')),
  result_note   text check (result_note is null or char_length(result_note) <= 500),
  completed_at  timestamptz,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);
create index staff_tasks_open_idx on public.staff_tasks (assigned_to, due_date) where status <> 'COMPLETED';
-- One open automatic task per target (no duplicates from repeated triggers).
create unique index staff_tasks_target_once_idx on public.staff_tasks (target_type, target_id) where status <> 'COMPLETED' and target_id is not null;
create trigger staff_tasks_set_updated_at before update on public.staff_tasks for each row execute function public.set_updated_at();

-- ─── Role helpers ───────────────────────────────────────────────────────────

create or replace function public.staff_kind()
returns text
language sql
stable
security definer
set search_path = public
as $$
  select case
    when public.is_admin() then 'ADMIN'
    when public.is_staff() then coalesce((select kind from public.staff_profiles where user_id = auth.uid()), 'MANAGER')
  end;
$$;

-- null = every campus.
create or replace function public.staff_campus()
returns text
language sql
stable
security definer
set search_path = public
as $$
  select case when public.staff_kind() in ('ADMIN', 'MANAGER') then null
              else (select campus_location from public.staff_profiles where user_id = auth.uid()) end;
$$;

create or replace function public.staff_can_see_lead(p_branch text, p_assigned uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select case public.staff_kind()
    when 'ADMIN' then true
    when 'MANAGER' then true
    when 'ADVISOR' then p_assigned = auth.uid() or public.staff_campus() is null or public.staff_campus() = p_branch
    when 'TEACHER' then public.staff_campus() is null or public.staff_campus() = p_branch
    else false end;
$$;

create or replace function public.staff_can_see_enrollment(p_enrollment_id uuid, p_campus text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select case public.staff_kind()
    when 'ADMIN' then true
    when 'MANAGER' then true
    when 'ADVISOR' then public.staff_campus() is null or public.staff_campus() = p_campus
    when 'TEACHER' then exists (select 1 from public.class_members m join public.classes c on c.id = m.class_id
                                 where m.enrollment_id = p_enrollment_id and c.teacher_id = auth.uid())
    else false end;
$$;

create or replace function public.staff_can_see_student(p_student_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select case
    when public.staff_kind() in ('ADMIN', 'MANAGER') then true
    when public.staff_kind() is null then false
    else exists (select 1 from public.enrollments e where e.student_id = p_student_id
                  and public.staff_can_see_enrollment(e.id, e.campus_location)) end;
$$;

create or replace function public.staff_owns_class(p_class_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  -- coalesce: for non-staff staff_kind() is null, and null must mean 'no', not 'unknown'.
  select coalesce(public.staff_kind() in ('ADMIN', 'MANAGER'), false)
      or exists (select 1 from public.classes where id = p_class_id and teacher_id = auth.uid());
$$;

-- ─── Row level security ─────────────────────────────────────────────────────

drop policy if exists "staff read leads" on public.leads;
drop policy if exists "staff update leads" on public.leads;
create policy "staff read leads in scope" on public.leads for select to authenticated
  using (public.staff_can_see_lead(branch_location, assigned_advisor));
create policy "staff update leads in scope" on public.leads for update to authenticated
  using (public.staff_can_see_lead(branch_location, assigned_advisor))
  with check (public.staff_can_see_lead(branch_location, assigned_advisor));

drop policy if exists "staff read crm logs" on public.crm_logs;
create policy "staff read crm logs in scope" on public.crm_logs for select to authenticated
  using (exists (select 1 from public.leads l where l.id = crm_logs.lead_id and public.staff_can_see_lead(l.branch_location, l.assigned_advisor)));

drop policy if exists "staff read enrollments" on public.enrollments;
create policy "staff read enrollments in scope" on public.enrollments for select to authenticated
  using (public.staff_can_see_enrollment(id, campus_location));

drop policy if exists "staff read lifecycle" on public.lifecycle_automations;
create policy "staff read lifecycle in scope" on public.lifecycle_automations for select to authenticated
  using (exists (select 1 from public.enrollments e where e.id = lifecycle_automations.enrollment_id
                  and public.staff_can_see_enrollment(e.id, e.campus_location)));

drop policy if exists "linked parents and staff read students" on public.students;
create policy "linked parents and staff read students" on public.students for select to authenticated
  using (public.parent_can_see(id) or public.staff_can_see_student(id));

drop policy if exists "linked parents and staff read reports" on public.daily_reports;
create policy "linked parents and staff read reports" on public.daily_reports for select to authenticated
  using (public.parent_can_see(student_id) or public.staff_can_see_student(student_id));

drop policy if exists "linked parents and staff read requests" on public.attendance_requests;
create policy "linked parents and staff read requests" on public.attendance_requests for select to authenticated
  using (public.parent_can_see(student_id) or public.staff_can_see_student(student_id));

drop policy if exists "staff read tuition invoices" on public.tuition_invoices;
create policy "staff read tuition invoices in scope" on public.tuition_invoices for select to authenticated
  using (public.staff_can_see_enrollment(enrollment_id, campus_location));

alter table public.staff_profiles enable row level security;
alter table public.classes enable row level security;
alter table public.class_members enable row level security;
alter table public.attendance_logs enable row level security;
alter table public.staff_tasks enable row level security;
create policy "staff read own profile, admin all" on public.staff_profiles for select to authenticated
  using (user_id = auth.uid() or public.staff_kind() in ('ADMIN', 'MANAGER'));
create policy "staff read classes in scope" on public.classes for select to authenticated
  using (public.staff_owns_class(id) or (public.staff_kind() = 'ADVISOR' and (public.staff_campus() is null or public.staff_campus() = campus_location)));
create policy "staff read class members in scope" on public.class_members for select to authenticated
  using (public.staff_owns_class(class_id));
create policy "staff and parents read attendance" on public.attendance_logs for select to authenticated
  using (public.staff_owns_class(class_id) or public.parent_can_see(student_id));
create policy "assignee and managers read tasks" on public.staff_tasks for select to authenticated
  using (assigned_to = auth.uid() or public.staff_kind() in ('ADMIN', 'MANAGER'));
revoke all on public.staff_profiles, public.classes, public.class_members, public.attendance_logs, public.staff_tasks from anon;
revoke insert, update, delete on public.staff_profiles, public.classes, public.class_members, public.attendance_logs, public.staff_tasks from authenticated;

-- Class photos (one upload for the whole class): class-reports/class/<class_id>/…
create or replace function public.storage_class_folder(p_name text)
returns uuid
language sql
immutable
as $$
  select case when split_part(p_name, '/', 1) = 'class'
               and split_part(p_name, '/', 2) ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              then split_part(p_name, '/', 2)::uuid end;
$$;
-- A parent with a child in the class (security definer: parents cannot read class_members themselves).
create or replace function public.parent_in_class(p_class_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (select 1 from public.class_members m join public.enrollments e on e.id = m.enrollment_id
                  where m.class_id = p_class_id and public.parent_can_see(e.student_id));
$$;

create policy "teachers upload class photos" on storage.objects for insert to authenticated
  with check (bucket_id = 'class-reports' and public.storage_class_folder(name) is not null and public.staff_owns_class(public.storage_class_folder(name)));
create policy "class teacher and class parents read class photos" on storage.objects for select to authenticated
  using (bucket_id = 'class-reports' and public.storage_class_folder(name) is not null
         and (public.staff_owns_class(public.storage_class_folder(name)) or public.parent_in_class(public.storage_class_folder(name))));

-- Per-student photos: staff only for students in their scope (was: every staff member).
drop policy if exists "linked parents and staff read class reports" on storage.objects;
create policy "linked parents and staff read class reports" on storage.objects for select to authenticated
  using (bucket_id = 'class-reports' and public.storage_student_folder(name) is not null
         and (public.staff_can_see_student(public.storage_student_folder(name)) or public.parent_can_see(public.storage_student_folder(name))));
drop policy if exists "staff upload class reports" on storage.objects;
create policy "staff upload class reports" on storage.objects for insert to authenticated
  with check (bucket_id = 'class-reports' and public.storage_student_folder(name) is not null
              and public.staff_can_see_student(public.storage_student_folder(name)));

-- ─── Guards on existing staff actions (scope) ───────────────────────────────
alter function public.crm_complete_trial(uuid, text) rename to crm_complete_trial_core;
alter function public.crm_set_status(uuid, text, text) rename to crm_set_status_core;
alter function public.enrollment_complete(uuid, text, date, smallint) rename to enrollment_complete_core;
alter function public.enrollment_drop(uuid, text) rename to enrollment_drop_core;
alter function public.enrollment_mark_contacted(uuid, text) rename to enrollment_mark_contacted_core;
alter function public.daily_report_create(uuid, date, text, text, jsonb) rename to daily_report_create_core;
revoke all on function public.crm_complete_trial_core(uuid, text) from public, anon, authenticated;
revoke all on function public.crm_set_status_core(uuid, text, text) from public, anon, authenticated;
revoke all on function public.enrollment_complete_core(uuid, text, date, smallint) from public, anon, authenticated;
revoke all on function public.enrollment_drop_core(uuid, text) from public, anon, authenticated;
revoke all on function public.enrollment_mark_contacted_core(uuid, text) from public, anon, authenticated;
revoke all on function public.daily_report_create_core(uuid, date, text, text, jsonb) from public, anon, authenticated;

create or replace function public.assert_lead_scope(p_lead_id uuid)
returns void
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  -- A missing id is left to the action itself (NOT_FOUND).
  if exists (select 1 from public.leads l where l.id = p_lead_id)
     and not exists (select 1 from public.leads l where l.id = p_lead_id and public.staff_can_see_lead(l.branch_location, l.assigned_advisor)) then
    raise exception 'Đăng ký này không thuộc phạm vi phụ trách của bạn' using hint = 'FORBIDDEN';
  end if;
end;
$$;

create or replace function public.assert_enrollment_scope(p_enrollment_id uuid)
returns void
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  if exists (select 1 from public.enrollments e where e.id = p_enrollment_id)
     and not exists (select 1 from public.enrollments e where e.id = p_enrollment_id and public.staff_can_see_enrollment(e.id, e.campus_location)) then
    raise exception 'Học viên này không thuộc lớp / cơ sở bạn phụ trách' using hint = 'FORBIDDEN';
  end if;
end;
$$;

create or replace function public.crm_complete_trial(p_lead_id uuid, p_teacher_note text)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
begin
  if public.is_staff() then perform public.assert_lead_scope(p_lead_id); end if;
  return public.crm_complete_trial_core(p_lead_id, p_teacher_note);
end; $$;

create or replace function public.crm_set_status(p_lead_id uuid, p_status text, p_note text default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
begin
  if public.is_staff() then perform public.assert_lead_scope(p_lead_id); end if;
  return public.crm_set_status_core(p_lead_id, p_status, p_note);
end; $$;

create or replace function public.enrollment_complete(p_enrollment_id uuid, p_teacher_note text, p_end_date date default null, p_level smallint default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
begin
  if public.is_staff() then perform public.assert_enrollment_scope(p_enrollment_id); end if;
  return public.enrollment_complete_core(p_enrollment_id, p_teacher_note, p_end_date, p_level);
end; $$;

create or replace function public.enrollment_drop(p_enrollment_id uuid, p_note text default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
begin
  if public.is_staff() then perform public.assert_enrollment_scope(p_enrollment_id); end if;
  return public.enrollment_drop_core(p_enrollment_id, p_note);
end; $$;

create or replace function public.enrollment_mark_contacted(p_enrollment_id uuid, p_note text default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
begin
  if public.is_staff() then perform public.assert_enrollment_scope(p_enrollment_id); end if;
  return public.enrollment_mark_contacted_core(p_enrollment_id, p_note);
end; $$;

create or replace function public.daily_report_create(p_enrollment_id uuid, p_session_date date, p_attendance text, p_feedback text, p_media jsonb default '[]'::jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
begin
  if public.is_staff() then perform public.assert_enrollment_scope(p_enrollment_id); end if;
  return public.daily_report_create_core(p_enrollment_id, p_session_date, p_attendance, p_feedback, p_media);
end; $$;

-- ─── Automatic tasks ────────────────────────────────────────────────────────

-- The campus advisor with the fewest open tasks (null if the campus has none).
create or replace function public.pick_advisor(p_campus text)
returns uuid
language sql
stable
security definer
set search_path = public
as $$
  select p.user_id from public.staff_profiles p
   where p.kind = 'ADVISOR' and (p.campus_location is null or p.campus_location = p_campus)
   order by (p.campus_location is null),
            (select count(*) from public.staff_tasks t where t.assigned_to = p.user_id and t.status <> 'COMPLETED'),
            p.user_id
   limit 1;
$$;

create or replace function public.leads_assign_advisor()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.assigned_advisor is null then
    new.assigned_advisor := public.pick_advisor(new.branch_location);
  end if;
  return new;
end;
$$;
create trigger leads_assign_advisor before insert on public.leads for each row execute function public.leads_assign_advisor();

create or replace function public.leads_followup_task()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.assigned_advisor is not null then
    insert into public.staff_tasks (assigned_to, title, description, target_type, target_id, due_date, priority)
    values (new.assigned_advisor,
            left('Gọi xác nhận học thử – ' || new.parent_name, 120),
            left(format('Bé %s (%s tuổi) · %s · %s', new.student_name, new.student_age, new.course_code, new.branch_location), 1000),
            'LEAD_FOLLOWUP', new.id, now() + interval '2 hours', 1)
    on conflict do nothing;
  end if;
  return null;
end;
$$;
create trigger leads_followup_task after insert on public.leads for each row execute function public.leads_followup_task();

-- Approved make-up request → the teacher of the child's class schedules it.
create or replace function public.attendance_request_task()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_teacher uuid;
  v_name    text;
begin
  if new.type = 'MAKEUP' and new.status = 'APPROVED' and old.status is distinct from 'APPROVED' then
    select c.teacher_id into v_teacher
      from public.class_members m join public.classes c on c.id = m.class_id join public.enrollments e on e.id = m.enrollment_id
     where e.student_id = new.student_id and c.is_active and c.teacher_id is not null
     order by e.status = 'ACTIVE' desc limit 1;
    if v_teacher is not null then
      select full_name into v_name from public.students where id = new.student_id;
      insert into public.staff_tasks (assigned_to, assigned_by, title, description, target_type, target_id, due_date, priority)
      values (v_teacher, new.decided_by, left('Xếp buổi học bù – ' || coalesce(v_name, 'học viên'), 120), left(new.reason, 1000),
              'MAKEUP_CLASS', new.id, (new.requested_date + time '09:00') at time zone 'Asia/Ho_Chi_Minh', 2)
      on conflict do nothing;
    end if;
  end if;
  return null;
end;
$$;
create trigger attendance_requests_task after update of status on public.attendance_requests
  for each row execute function public.attendance_request_task();

-- T+14 after a course: the advisor calls about the next course.
create or replace function public.enrollment_advisor_task()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_advisor uuid;
begin
  if new.advisor_priority and not coalesce(old.advisor_priority, false) and new.lead_id is not null then
    select coalesce(l.assigned_advisor, public.pick_advisor(new.campus_location)) into v_advisor from public.leads l where l.id = new.lead_id;
    if v_advisor is not null then
      insert into public.staff_tasks (assigned_to, title, description, target_type, target_id, due_date, priority)
      values (v_advisor, left('Gọi tư vấn khóa tiếp theo – ' || new.student_name, 120),
              'Học viên đã hoàn thành khóa ' || new.course_code || ' 14 ngày trước.', 'LEAD_FOLLOWUP', new.lead_id, now() + interval '1 day', 2)
      on conflict do nothing;
    end if;
  end if;
  return null;
end;
$$;
create trigger enrollments_advisor_task after update of advisor_priority on public.enrollments
  for each row execute function public.enrollment_advisor_task();

-- ─── Tasks API ──────────────────────────────────────────────────────────────

-- p_scope: MINE (default) | ALL (admin / manager). p_status: OPEN | DONE.
create or replace function public.staff_task_list(p_scope text default 'MINE', p_status text default 'OPEN')
returns jsonb
language plpgsql
stable
security definer
set search_path = public, auth
as $$
declare
  v_all boolean := coalesce(p_scope, 'MINE') = 'ALL' and public.staff_kind() in ('ADMIN', 'MANAGER');
begin
  if public.staff_kind() is null then
    raise exception 'Chỉ nhân viên TH EDU' using hint = 'FORBIDDEN';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', t.id, 'title', t.title, 'description', t.description, 'target_type', t.target_type, 'target_id', t.target_id,
      'due_date', t.due_date, 'priority', t.priority, 'status', t.status, 'result_note', t.result_note,
      'completed_at', t.completed_at, 'created_at', t.created_at, 'auto', t.assigned_by is null,
      'assignee', coalesce(sp.display_name, au.email::text),
      'lead', case when t.target_type = 'LEAD_FOLLOWUP' then (
        select jsonb_build_object('id', l.id, 'code', l.code, 'parent_name', l.parent_name, 'phone', l.phone_number,
                                  'student_name', l.student_name, 'course_code', l.course_code, 'branch', l.branch_location,
                                  'status', l.status, 'appointment_time', l.appointment_time)
        from public.leads l where l.id = t.target_id) end,
      'request', case when t.target_type = 'MAKEUP_CLASS' then (
        select jsonb_build_object('id', a.id, 'requested_date', a.requested_date, 'reason', a.reason, 'student_name', s.full_name,
                                  'parent_phone', u.phone)
        from public.attendance_requests a join public.students s on s.id = a.student_id left join public.users u on u.id = a.parent_id
        where a.id = t.target_id) end)
      order by t.status = 'COMPLETED', t.priority, t.due_date)
    from public.staff_tasks t
    left join public.staff_profiles sp on sp.user_id = t.assigned_to
    left join auth.users au on au.id = t.assigned_to
    where (v_all or t.assigned_to = auth.uid())
      and (case when coalesce(p_status, 'OPEN') = 'DONE' then t.status = 'COMPLETED' and t.completed_at > now() - interval '14 days'
                else t.status <> 'COMPLETED' end)), '[]'::jsonb);
end;
$$;

create or replace function public.staff_task_update(p_task_id uuid, p_status text, p_note text default null)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v public.staff_tasks;
begin
  if p_status not in ('PENDING', 'IN_PROGRESS', 'COMPLETED') then
    raise exception 'Trạng thái không hợp lệ' using hint = 'VALIDATION:status';
  end if;
  if p_note is not null and char_length(p_note) > 500 then
    raise exception 'Ghi chú tối đa 500 ký tự' using hint = 'VALIDATION:note';
  end if;
  update public.staff_tasks
     set status = p_status,
         completed_at = case when p_status = 'COMPLETED' then now() end,
         result_note = coalesce(nullif(btrim(coalesce(p_note, '')), ''), result_note)
   where id = p_task_id and (assigned_to = auth.uid() or public.staff_kind() in ('ADMIN', 'MANAGER'))
  returning * into v;
  if not found then
    raise exception 'Không tìm thấy công việc của bạn' using hint = 'NOT_FOUND';
  end if;
  return jsonb_build_object('id', v.id, 'status', v.status);
end;
$$;

create or replace function public.staff_task_create(p_assigned_to uuid, p_title text, p_description text, p_type text,
                                                     p_target_id uuid, p_due timestamptz, p_priority int default 2)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_id uuid;
begin
  if public.staff_kind() not in ('ADMIN', 'MANAGER') then
    raise exception 'Chỉ quản trị / quản lý được giao việc' using hint = 'FORBIDDEN';
  end if;
  if not exists (select 1 from auth.users u where u.id = p_assigned_to and u.raw_app_meta_data ->> 'role' in ('staff', 'admin')) then
    raise exception 'Người nhận không phải nhân viên' using hint = 'VALIDATION:assigned_to';
  end if;
  if char_length(btrim(coalesce(p_title, ''))) not between 3 and 120 then
    raise exception 'Tiêu đề 3–120 ký tự' using hint = 'VALIDATION:title';
  end if;
  if p_type not in ('LEAD_FOLLOWUP', 'MAKEUP_CLASS', 'HOMEWORK_GRADE', 'OTHER') then
    raise exception 'Loại công việc không hợp lệ' using hint = 'VALIDATION:type';
  end if;
  if p_due is null then
    raise exception 'Chọn hạn hoàn thành' using hint = 'VALIDATION:due';
  end if;
  insert into public.staff_tasks (assigned_to, assigned_by, title, description, target_type, target_id, due_date, priority)
  values (p_assigned_to, auth.uid(), btrim(p_title), nullif(btrim(coalesce(p_description, '')), ''), p_type, p_target_id, p_due,
          greatest(1, least(3, coalesce(p_priority, 2))))
  returning id into v_id;
  return jsonb_build_object('id', v_id);
exception when unique_violation then
  raise exception 'Đối tượng này đã có một công việc đang mở' using hint = 'CONFLICT';
end;
$$;

-- ─── Staff directory & roles (admin) ────────────────────────────────────────

create or replace function public.staff_directory()
returns jsonb
language plpgsql
stable
security definer
set search_path = public, auth
as $$
begin
  if public.staff_kind() not in ('ADMIN', 'MANAGER') then
    raise exception 'Chỉ quản trị / quản lý' using hint = 'FORBIDDEN';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', u.id, 'email', u.email, 'role', u.raw_app_meta_data ->> 'role',
      'display_name', coalesce(p.display_name, nullif(u.raw_user_meta_data ->> 'display_name', '')),
      'kind', case when u.raw_app_meta_data ->> 'role' = 'admin' then 'ADMIN' else coalesce(p.kind, 'MANAGER') end,
      'has_profile', p.user_id is not null, 'campus_location', p.campus_location,
      'open_tasks', (select count(*) from public.staff_tasks t where t.assigned_to = u.id and t.status <> 'COMPLETED'))
      order by u.raw_app_meta_data ->> 'role' = 'admin' desc, u.created_at)
    from auth.users u left join public.staff_profiles p on p.user_id = u.id
    where u.raw_app_meta_data ->> 'role' in ('staff', 'admin')), '[]'::jsonb);
end;
$$;

create or replace function public.admin_staff_profile_set(p_user_id uuid, p_kind text, p_campus text, p_display_name text default null)
returns void
language plpgsql
volatile
security definer
set search_path = public, auth
as $$
begin
  if not public.is_admin() then
    raise exception 'Chỉ quản trị viên được phân vai trò' using hint = 'FORBIDDEN';
  end if;
  if p_kind not in ('TEACHER', 'ADVISOR', 'MANAGER') then
    raise exception 'Vai trò không hợp lệ' using hint = 'VALIDATION:kind';
  end if;
  if p_campus is not null and not exists (select 1 from public.branches where code = p_campus) then
    raise exception 'Cơ sở không hợp lệ' using hint = 'VALIDATION:campus';
  end if;
  if not exists (select 1 from auth.users where id = p_user_id and raw_app_meta_data ->> 'role' = 'staff') then
    raise exception 'Chỉ phân vai trò cho tài khoản giáo viên / nhân viên' using hint = 'VALIDATION:user';
  end if;
  insert into public.staff_profiles (user_id, kind, campus_location, display_name, updated_by)
  values (p_user_id, p_kind, p_campus, nullif(btrim(coalesce(p_display_name, '')), ''), auth.uid())
  on conflict (user_id) do update
     set kind = excluded.kind, campus_location = excluded.campus_location,
         display_name = coalesce(excluded.display_name, public.staff_profiles.display_name),
         updated_by = auth.uid(), updated_at = now();
end;
$$;

-- ─── Classes (admin / manager) ──────────────────────────────────────────────

create or replace function public.class_list()
returns jsonb
language plpgsql
stable
security definer
set search_path = public, auth
as $$
begin
  if public.staff_kind() is null then
    raise exception 'Chỉ nhân viên TH EDU' using hint = 'FORBIDDEN';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', c.id, 'name', c.name, 'course_code', c.course_code, 'level', c.level, 'campus_location', c.campus_location,
      'teacher_id', c.teacher_id, 'teacher_name', coalesce(p.display_name, au.email::text), 'schedule', c.schedule,
      'is_active', c.is_active, 'members', (select count(*) from public.class_members m where m.class_id = c.id))
      order by c.is_active desc, c.campus_location, c.name)
    from public.classes c
    left join public.staff_profiles p on p.user_id = c.teacher_id
    left join auth.users au on au.id = c.teacher_id
    where public.staff_owns_class(c.id)), '[]'::jsonb);
end;
$$;

create or replace function public.admin_class_upsert(p jsonb)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, auth
as $$
declare
  v_id      uuid := nullif(p ->> 'id', '')::uuid;
  v_teacher uuid := nullif(p ->> 'teacher_id', '')::uuid;
  v_row     public.classes;
begin
  if public.staff_kind() not in ('ADMIN', 'MANAGER') then
    raise exception 'Chỉ quản trị / quản lý được sửa lớp học' using hint = 'FORBIDDEN';
  end if;
  if char_length(btrim(coalesce(p ->> 'name', ''))) not between 2 and 60 then
    raise exception 'Tên lớp 2–60 ký tự' using hint = 'VALIDATION:name';
  end if;
  if not exists (select 1 from public.categories where code = p ->> 'course_code') then
    raise exception 'Chọn khóa học' using hint = 'VALIDATION:course_code';
  end if;
  if not exists (select 1 from public.branches where code = p ->> 'campus_location') then
    raise exception 'Chọn cơ sở' using hint = 'VALIDATION:campus_location';
  end if;
  if v_teacher is not null and not exists (select 1 from auth.users where id = v_teacher and raw_app_meta_data ->> 'role' in ('staff', 'admin')) then
    raise exception 'Giáo viên không hợp lệ' using hint = 'VALIDATION:teacher_id';
  end if;
  if jsonb_typeof(coalesce(p -> 'schedule', '[]'::jsonb)) <> 'array' then
    raise exception 'Lịch học không hợp lệ' using hint = 'VALIDATION:schedule';
  end if;
  if v_id is null then
    insert into public.classes (name, course_code, level, campus_location, teacher_id, schedule, created_by)
    values (btrim(p ->> 'name'), p ->> 'course_code', greatest(1, least(5, coalesce(nullif(p ->> 'level', '')::int, 1))),
            p ->> 'campus_location', v_teacher, coalesce(p -> 'schedule', '[]'::jsonb), auth.uid())
    returning * into v_row;
  else
    update public.classes
       set name = btrim(p ->> 'name'), course_code = p ->> 'course_code',
           level = greatest(1, least(5, coalesce(nullif(p ->> 'level', '')::int, level))),
           campus_location = p ->> 'campus_location', teacher_id = v_teacher,
           schedule = coalesce(p -> 'schedule', schedule), is_active = coalesce((p ->> 'is_active')::boolean, is_active)
     where id = v_id
    returning * into v_row;
    if not found then
      raise exception 'Không tìm thấy lớp' using hint = 'NOT_FOUND';
    end if;
  end if;
  return jsonb_build_object('id', v_row.id);
end;
$$;

-- Active enrollments that fit a class (same course + campus) with their membership.
create or replace function public.class_candidates(p_class_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v public.classes;
begin
  if public.staff_kind() not in ('ADMIN', 'MANAGER') then
    raise exception 'Chỉ quản trị / quản lý' using hint = 'FORBIDDEN';
  end if;
  select * into v from public.classes where id = p_class_id;
  if not found then
    raise exception 'Không tìm thấy lớp' using hint = 'NOT_FOUND';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'enrollment_id', e.id, 'student_name', e.student_name, 'student_id', e.student_id, 'level', e.level,
      'in_class', exists (select 1 from public.class_members m where m.class_id = v.id and m.enrollment_id = e.id),
      'other_class', (select c2.name from public.class_members m2 join public.classes c2 on c2.id = m2.class_id
                       where m2.enrollment_id = e.id and c2.id <> v.id and c2.is_active limit 1))
      order by e.student_name)
    from public.enrollments e
    where e.status = 'ACTIVE' and e.course_code = v.course_code and e.campus_location = v.campus_location), '[]'::jsonb);
end;
$$;

create or replace function public.admin_class_members_set(p_class_id uuid, p_enrollment_ids uuid[])
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v public.classes;
  n int;
begin
  if public.staff_kind() not in ('ADMIN', 'MANAGER') then
    raise exception 'Chỉ quản trị / quản lý' using hint = 'FORBIDDEN';
  end if;
  select * into v from public.classes where id = p_class_id for update;
  if not found then
    raise exception 'Không tìm thấy lớp' using hint = 'NOT_FOUND';
  end if;
  if exists (select 1 from unnest(coalesce(p_enrollment_ids, '{}')) x(id)
              left join public.enrollments e on e.id = x.id
              where e.id is null or e.course_code <> v.course_code or e.campus_location <> v.campus_location) then
    raise exception 'Chỉ thêm học viên cùng khóa và cùng cơ sở với lớp' using hint = 'VALIDATION:enrollment_ids';
  end if;
  delete from public.class_members where class_id = v.id and enrollment_id <> all (coalesce(p_enrollment_ids, '{}'));
  insert into public.class_members (class_id, enrollment_id)
  select v.id, x.id from unnest(coalesce(p_enrollment_ids, '{}')) x(id) on conflict do nothing;
  select count(*) into n from public.class_members where class_id = v.id;
  return jsonb_build_object('id', v.id, 'members', n);
end;
$$;

-- ─── Teacher: roster, attendance, batch reports ─────────────────────────────

create or replace function public.class_roster(p_class_id uuid, p_date date default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_date date := coalesce(p_date, (now() at time zone 'Asia/Ho_Chi_Minh')::date);
begin
  if not public.staff_owns_class(p_class_id) then
    raise exception 'Bạn không phụ trách lớp này' using hint = 'FORBIDDEN';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'enrollment_id', e.id, 'student_id', e.student_id, 'student_name', coalesce(s.full_name, e.student_name),
      'sessions_remaining', e.sessions_remaining, 'linked', e.student_id is not null,
      'attendance', (select jsonb_build_object('status', a.status, 'method', a.method, 'time', a.check_in_time)
                       from public.attendance_logs a where a.class_id = p_class_id and a.student_id = e.student_id and a.session_date = v_date),
      'reported', exists (select 1 from public.daily_reports r where r.student_id = e.student_id and r.course_code = e.course_code and r.session_date = v_date))
      order by coalesce(s.full_name, e.student_name))
    from public.class_members m
    join public.enrollments e on e.id = m.enrollment_id and e.status = 'ACTIVE'
    left join public.students s on s.id = e.student_id
    where m.class_id = p_class_id), '[]'::jsonb);
end;
$$;

create or replace function public.attendance_mark(p_class_id uuid, p_student_id uuid, p_status text, p_method text default 'MANUAL', p_date date default null)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_date  date := coalesce(p_date, (now() at time zone 'Asia/Ho_Chi_Minh')::date);
  v_enr   uuid;
  v_row   public.attendance_logs;
begin
  if not public.staff_owns_class(p_class_id) then
    raise exception 'Bạn không phụ trách lớp này' using hint = 'FORBIDDEN';
  end if;
  if p_status not in ('PRESENT', 'LATE', 'ABSENT', 'EXCUSED') or p_method not in ('QR', 'MANUAL') then
    raise exception 'Trạng thái điểm danh không hợp lệ' using hint = 'VALIDATION:status';
  end if;
  if v_date > (now() at time zone 'Asia/Ho_Chi_Minh')::date or v_date < (now() at time zone 'Asia/Ho_Chi_Minh')::date - 7 then
    raise exception 'Chỉ điểm danh trong 7 ngày gần nhất' using hint = 'VALIDATION:date';
  end if;
  select e.id into v_enr from public.class_members m join public.enrollments e on e.id = m.enrollment_id
   where m.class_id = p_class_id and e.student_id = p_student_id and e.status = 'ACTIVE' limit 1;
  if v_enr is null then
    raise exception 'Học viên không có trong lớp này' using hint = 'NOT_FOUND';
  end if;
  insert into public.attendance_logs (student_id, class_id, enrollment_id, session_date, scanned_by, status, method)
  values (p_student_id, p_class_id, v_enr, v_date, auth.uid(), p_status, p_method)
  on conflict (class_id, student_id, session_date) do update
     set status = excluded.status, method = excluded.method, scanned_by = excluded.scanned_by, check_in_time = now()
  returning * into v_row;
  return jsonb_build_object('student_id', v_row.student_id, 'status', v_row.status);
end;
$$;

-- QR check-in: PRESENT, or LATE if more than 10 minutes after today's class start (from the class schedule).
create or replace function public.attendance_scan(p_class_id uuid, p_token text)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_now    timestamp := now() at time zone 'Asia/Ho_Chi_Minh';
  v_class  public.classes;
  v_s      public.students;
  v_start  text;
  v_status text := 'PRESENT';
  v_prev   text;
begin
  if not public.staff_owns_class(p_class_id) then
    raise exception 'Bạn không phụ trách lớp này' using hint = 'FORBIDDEN';
  end if;
  select * into v_class from public.classes where id = p_class_id;
  select * into v_s from public.students
   where qr_token = upper(regexp_replace(regexp_replace(coalesce(p_token, ''), '^THEDU-HS:', '', 'i'), '\s', '', 'g'));
  if not found then
    raise exception 'Mã QR không đúng — không tìm thấy học viên' using hint = 'NOT_FOUND';
  end if;
  select x ->> 'start' into v_start from jsonb_array_elements(v_class.schedule) x
   where (x ->> 'd')::int = case when extract(isodow from v_now) = 7 then 8 else extract(isodow from v_now)::int + 1 end
   limit 1;
  if v_start ~ '^\d{2}:\d{2}$' and v_now::time > v_start::time + interval '10 minutes' then
    v_status := 'LATE';
  end if;
  select status into v_prev from public.attendance_logs
   where class_id = p_class_id and student_id = v_s.id and session_date = v_now::date;
  if v_prev in ('PRESENT', 'LATE') then
    return jsonb_build_object('student_id', v_s.id, 'student_name', v_s.full_name, 'status', v_prev, 'already', true);
  end if;
  perform public.attendance_mark(p_class_id, v_s.id, v_status, 'QR', v_now::date);
  return jsonb_build_object('student_id', v_s.id, 'student_name', v_s.full_name, 'status', v_status, 'already', false);
end;
$$;

-- One contact-book entry per selected student (shared class photos + tags + note); sessions used for PRESENT/LATE.
create or replace function public.daily_report_batch(p_class_id uuid, p_session_date date, p_student_ids uuid[],
                                                      p_feedback text, p_tags text[] default '{}', p_media jsonb default '[]'::jsonb)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, auth
as $$
declare
  v_class   public.classes;
  v_today   date := (now() at time zone 'Asia/Ho_Chi_Minh')::date;
  v_teacher text;
  v_sid     uuid;
  v_e       public.enrollments;
  v_att     text;
  v_created int := 0;
  v_skipped int := 0;
  m         text;
begin
  if not public.staff_owns_class(p_class_id) then
    raise exception 'Bạn không phụ trách lớp này' using hint = 'FORBIDDEN';
  end if;
  select * into v_class from public.classes where id = p_class_id;
  if coalesce(cardinality(p_student_ids), 0) = 0 then
    raise exception 'Chọn ít nhất 1 học viên' using hint = 'VALIDATION:students';
  end if;
  if p_session_date is null or p_session_date > v_today or p_session_date < v_today - 30 then
    raise exception 'Ngày học trong vòng 30 ngày qua' using hint = 'VALIDATION:session_date';
  end if;
  if p_feedback is not null and char_length(p_feedback) > 2000 then
    raise exception 'Nhận xét tối đa 2000 ký tự' using hint = 'VALIDATION:feedback';
  end if;
  if coalesce(cardinality(p_tags), 0) > 8 or exists (select 1 from unnest(coalesce(p_tags, '{}')) t where char_length(t) not between 2 and 40) then
    raise exception 'Tối đa 8 nhận xét nhanh' using hint = 'VALIDATION:tags';
  end if;
  if jsonb_typeof(coalesce(p_media, '[]'::jsonb)) <> 'array' or jsonb_array_length(coalesce(p_media, '[]'::jsonb)) > 6 then
    raise exception 'Tối đa 6 ảnh' using hint = 'VALIDATION:media';
  end if;
  for m in select jsonb_array_elements_text(coalesce(p_media, '[]'::jsonb)) loop
    if public.storage_class_folder(m) is distinct from p_class_id then
      raise exception 'Ảnh không thuộc lớp này' using hint = 'VALIDATION:media';
    end if;
  end loop;

  select coalesce(p.display_name, nullif(btrim(u.raw_user_meta_data ->> 'full_name'), ''), nullif(btrim(u.raw_user_meta_data ->> 'display_name'), ''), split_part(u.email, '@', 1))
    into v_teacher from auth.users u left join public.staff_profiles p on p.user_id = u.id where u.id = auth.uid();

  foreach v_sid in array p_student_ids loop
    select e.* into v_e from public.class_members cm join public.enrollments e on e.id = cm.enrollment_id
     where cm.class_id = p_class_id and e.student_id = v_sid and e.status = 'ACTIVE' limit 1;
    if v_e.id is null then
      raise exception 'Có học viên không thuộc lớp này' using hint = 'VALIDATION:students';
    end if;
    select case status when 'LATE' then 'PRESENT' else status end into v_att from public.attendance_logs
     where class_id = p_class_id and student_id = v_sid and session_date = p_session_date;
    v_att := coalesce(v_att, 'PRESENT');
    begin
      insert into public.daily_reports (student_id, enrollment_id, class_id, course_code, session_date, attendance, teacher_name,
                                        feedback_text, media_urls, tags, created_by)
      values (v_sid, v_e.id, p_class_id, v_e.course_code, p_session_date, v_att, left(coalesce(v_teacher, 'Giáo viên'), 60),
              nullif(btrim(coalesce(p_feedback, '')), ''), coalesce(p_media, '[]'::jsonb), coalesce(p_tags, '{}'), auth.uid());
      v_created := v_created + 1;
      if v_att = 'PRESENT' and v_e.sessions_remaining is not null then
        update public.enrollments set sessions_remaining = greatest(sessions_remaining - 1, 0) where id = v_e.id;
      end if;
    exception when unique_violation then
      v_skipped := v_skipped + 1;   -- already written for this session
    end;
    v_e := null;
  end loop;
  return jsonb_build_object('created', v_created, 'skipped', v_skipped);
end;
$$;

-- Parent: the child's check-in QR content.
create or replace function public.parent_student_qr(p_student_id uuid)
returns text
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  if not public.parent_can_see(p_student_id) then
    raise exception 'Không có quyền' using hint = 'FORBIDDEN';
  end if;
  return (select 'THEDU-HS:' || qr_token from public.students where id = p_student_id);
end;
$$;

-- parent_reports now also returns the quick tags.
create or replace function public.parent_reports(p_student_id uuid, p_before date default null, p_limit int default 10)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  if not public.parent_can_see(p_student_id) and not public.staff_can_see_student(p_student_id) then
    raise exception 'Không có quyền xem sổ liên lạc của học viên này' using hint = 'FORBIDDEN';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', r.id, 'course_code', r.course_code, 'course_name', c.name, 'session_date', r.session_date,
      'attendance', r.attendance, 'teacher_name', r.teacher_name, 'feedback_text', r.feedback_text,
      'media_urls', r.media_urls, 'tags', r.tags, 'parent_liked', r.parent_liked, 'parent_reply', r.parent_reply,
      'parent_replied_at', r.parent_replied_at, 'created_at', r.created_at) order by r.session_date desc, r.created_at desc)
    from (select * from public.daily_reports
           where student_id = p_student_id and (p_before is null or session_date < p_before)
           order by session_date desc, created_at desc
           limit least(greatest(coalesce(p_limit, 10), 1), 30)) r
    join public.categories c on c.code = r.course_code), '[]'::jsonb);
end;
$$;

-- ─── Grants ─────────────────────────────────────────────────────────────────
do $$
declare f text;
begin
  foreach f in array array[
    'public.staff_kind()', 'public.staff_campus()', 'public.staff_can_see_lead(text, uuid)', 'public.staff_can_see_enrollment(uuid, text)',
    'public.staff_can_see_student(uuid)', 'public.staff_owns_class(uuid)',
    'public.crm_complete_trial(uuid, text)', 'public.crm_set_status(uuid, text, text)',
    'public.enrollment_complete(uuid, text, date, smallint)', 'public.enrollment_drop(uuid, text)', 'public.enrollment_mark_contacted(uuid, text)',
    'public.daily_report_create(uuid, date, text, text, jsonb)',
    'public.staff_task_list(text, text)', 'public.staff_task_update(uuid, text, text)',
    'public.staff_task_create(uuid, text, text, text, uuid, timestamptz, int)', 'public.staff_directory()',
    'public.admin_staff_profile_set(uuid, text, text, text)', 'public.class_list()', 'public.admin_class_upsert(jsonb)',
    'public.class_candidates(uuid)', 'public.admin_class_members_set(uuid, uuid[])', 'public.class_roster(uuid, date)',
    'public.attendance_mark(uuid, uuid, text, text, date)', 'public.attendance_scan(uuid, text)',
    'public.daily_report_batch(uuid, date, uuid[], text, text[], jsonb)', 'public.parent_student_qr(uuid)', 'public.parent_in_class(uuid)',
    'public.parent_reports(uuid, date, int)'] loop
    execute format('revoke all on function %s from public, anon', f);
    execute format('grant execute on function %s to authenticated', f);
  end loop;
  foreach f in array array['public.assert_lead_scope(uuid)', 'public.assert_enrollment_scope(uuid)', 'public.pick_advisor(text)',
                           'public.leads_assign_advisor()', 'public.leads_followup_task()', 'public.attendance_request_task()',
                           'public.enrollment_advisor_task()'] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
  end loop;
end $$;

-- ───────────────── 20261127090000_parent_engagement.sql ─────────────────
-- ─────────────────────────────────────────────────────────────────────────────
-- Parent engagement: AI notebook check log, classroom "flash" moments (photo / 5-second voice note from the
-- teacher during class) with reactions and replies.
--
--   ai_checks       one row per AI notebook check: who, when, kind, result. The photo is NOT stored —
--                   the Edge Function sends it to the model and forgets it. 10 checks per parent per day.
--   class_flashes   a teacher's moment for one class (PHOTO | AUDIO ≤ 6 s), kept 7 days, files in the private
--                   bucket class-reports under class/<class_id>/…; visible to that class's parents and teacher.
--   flash_reactions HEART ("Thả tim") / PROUD ("Tự hào quá") — one of each per parent per flash (toggle).
--   flash_replies   short parent replies the teacher reads.
-- ─────────────────────────────────────────────────────────────────────────────

create table public.ai_checks (
  id            uuid primary key default gen_random_uuid(),
  parent_id     uuid not null references public.users (id) on delete cascade,
  kind          text not null check (kind in ('HANDWRITING', 'MATH')),
  status        text not null default 'PENDING' check (status in ('PENDING', 'DONE', 'FAILED')),
  result        jsonb,
  error         text,
  created_at    timestamptz not null default now(),
  finished_at   timestamptz
);
create index ai_checks_parent_idx on public.ai_checks (parent_id, created_at desc);

create table public.class_flashes (
  id            uuid primary key default gen_random_uuid(),
  class_id      uuid not null references public.classes (id) on delete cascade,
  teacher_id    uuid references auth.users (id) on delete set null,
  teacher_name  text not null,
  kind          text not null check (kind in ('PHOTO', 'AUDIO')),
  media_path    text not null,
  caption       text check (caption is null or char_length(caption) <= 120),
  duration_sec  numeric(4, 1) check (duration_sec is null or duration_sec between 0 and 6),
  created_at    timestamptz not null default now(),
  expires_at    timestamptz not null default now() + interval '7 days'
);
create index class_flashes_class_idx on public.class_flashes (class_id, created_at desc);

create table public.flash_reactions (
  flash_id    uuid not null references public.class_flashes (id) on delete cascade,
  parent_id   uuid not null references public.users (id) on delete cascade,
  reaction    text not null check (reaction in ('HEART', 'PROUD')),
  created_at  timestamptz not null default now(),
  primary key (flash_id, parent_id, reaction)
);

create table public.flash_replies (
  id          uuid primary key default gen_random_uuid(),
  flash_id    uuid not null references public.class_flashes (id) on delete cascade,
  parent_id   uuid references public.users (id) on delete set null,
  parent_name text not null,
  body        text not null check (char_length(btrim(body)) between 1 and 300),
  created_at  timestamptz not null default now()
);
create index flash_replies_flash_idx on public.flash_replies (flash_id, created_at);

alter table public.ai_checks enable row level security;
alter table public.class_flashes enable row level security;
alter table public.flash_reactions enable row level security;
alter table public.flash_replies enable row level security;
create policy "parent reads own ai checks" on public.ai_checks for select to authenticated
  using (parent_id = public.current_parent_id());
create policy "class parents and teacher read flashes" on public.class_flashes for select to authenticated
  using (public.staff_owns_class(class_id) or public.parent_in_class(class_id));
revoke all on public.ai_checks, public.class_flashes, public.flash_reactions, public.flash_replies from anon;
revoke insert, update, delete on public.ai_checks, public.class_flashes, public.flash_reactions, public.flash_replies from authenticated;

-- Voice notes in the private bucket (photos were already allowed).
update storage.buckets
   set allowed_mime_types = array['image/jpeg', 'image/png', 'image/webp', 'audio/webm', 'audio/mp4', 'audio/mpeg', 'audio/ogg', 'audio/aac', 'audio/x-m4a']
 where id = 'class-reports';

-- Safety: never null for non-staff (same fix as in staff_rbac_tasks, for databases that ran the older copy).
create or replace function public.staff_owns_class(p_class_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  -- coalesce: for non-staff staff_kind() is null, and null must mean 'no', not 'unknown'.
  select coalesce(public.staff_kind() in ('ADMIN', 'MANAGER'), false)
      or exists (select 1 from public.classes where id = p_class_id and teacher_id = auth.uid());
$$;

-- ─── AI checks (service role, called by the Edge Function) ──────────────────

-- Start a check for the parent behind this auth user; enforces the daily limit.
create or replace function public.ai_check_begin(p_auth_user_id uuid, p_kind text)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_parent uuid;
  v_id     uuid;
  v_used   int;
begin
  select id into v_parent from public.users where auth_user_id = p_auth_user_id and is_active and role = 'PARENT';
  if v_parent is null then
    raise exception 'Cần đăng nhập tài khoản phụ huynh' using hint = 'UNAUTHORIZED';
  end if;
  if p_kind not in ('HANDWRITING', 'MATH') then
    raise exception 'Loại bài không hợp lệ' using hint = 'VALIDATION:kind';
  end if;
  select count(*) into v_used from public.ai_checks
   where parent_id = v_parent and created_at > date_trunc('day', now() at time zone 'Asia/Ho_Chi_Minh') at time zone 'Asia/Ho_Chi_Minh';
  if v_used >= 10 then
    raise exception 'Hôm nay ba mẹ đã dùng hết 10 lượt chấm. Mai mình chấm tiếp nhé!' using hint = 'RATE_LIMITED';
  end if;
  insert into public.ai_checks (parent_id, kind) values (v_parent, p_kind) returning id into v_id;
  return jsonb_build_object('id', v_id, 'remaining', 9 - v_used);
end;
$$;

create or replace function public.ai_check_finish(p_id uuid, p_ok boolean, p_result jsonb, p_error text default null)
returns void
language sql
volatile
security definer
set search_path = public
as $$
  update public.ai_checks
     set status = case when p_ok then 'DONE' else 'FAILED' end, result = p_result, error = left(p_error, 500), finished_at = now()
   where id = p_id;
$$;

-- ─── Classroom flash ────────────────────────────────────────────────────────

create or replace function public.flash_create(p_class_id uuid, p_kind text, p_path text, p_caption text default null, p_duration numeric default null)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, auth
as $$
declare
  v_teacher text;
  v_id      uuid;
begin
  if not public.staff_owns_class(p_class_id) then
    raise exception 'Bạn không phụ trách lớp này' using hint = 'FORBIDDEN';
  end if;
  if p_kind not in ('PHOTO', 'AUDIO') then
    raise exception 'Loại không hợp lệ' using hint = 'VALIDATION:kind';
  end if;
  if public.storage_class_folder(p_path) is distinct from p_class_id then
    raise exception 'Tệp không thuộc lớp này' using hint = 'VALIDATION:path';
  end if;
  if p_kind = 'AUDIO' and (p_duration is null or p_duration > 6) then
    raise exception 'Ghi âm tối đa 5 giây' using hint = 'VALIDATION:duration';
  end if;
  if p_caption is not null and char_length(p_caption) > 120 then
    raise exception 'Chú thích tối đa 120 ký tự' using hint = 'VALIDATION:caption';
  end if;
  select coalesce(p.display_name, nullif(btrim(u.raw_user_meta_data ->> 'full_name'), ''), nullif(btrim(u.raw_user_meta_data ->> 'display_name'), ''), split_part(u.email, '@', 1))
    into v_teacher from auth.users u left join public.staff_profiles p on p.user_id = u.id where u.id = auth.uid();
  insert into public.class_flashes (class_id, teacher_id, teacher_name, kind, media_path, caption, duration_sec)
  values (p_class_id, auth.uid(), left(coalesce(v_teacher, 'Giáo viên'), 60), p_kind, p_path, nullif(btrim(coalesce(p_caption, '')), ''), p_duration)
  returning id into v_id;
  return jsonb_build_object('id', v_id);
end;
$$;

-- Parent: moments of the last 7 days from my children's classes (+ my reactions, counts).
-- Teacher / admin: p_class_id = a class they own (with replies).
create or replace function public.flash_feed(p_class_id uuid default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_parent uuid := public.current_parent_id();
begin
  if p_class_id is not null and not public.staff_owns_class(p_class_id) then
    raise exception 'Bạn không phụ trách lớp này' using hint = 'FORBIDDEN';
  end if;
  if p_class_id is null and v_parent is null then
    raise exception 'Cần đăng nhập tài khoản phụ huynh' using hint = 'UNAUTHORIZED';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', f.id, 'class_id', f.class_id, 'class_name', c.name, 'teacher_name', f.teacher_name, 'kind', f.kind,
      'media_path', f.media_path, 'caption', f.caption, 'duration_sec', f.duration_sec, 'created_at', f.created_at,
      'hearts', (select count(*) from public.flash_reactions r where r.flash_id = f.id and r.reaction = 'HEART'),
      'prouds', (select count(*) from public.flash_reactions r where r.flash_id = f.id and r.reaction = 'PROUD'),
      'my_reactions', coalesce((select jsonb_agg(r.reaction) from public.flash_reactions r where r.flash_id = f.id and r.parent_id = v_parent), '[]'::jsonb),
      'replies', case when p_class_id is not null then coalesce((
                   select jsonb_agg(jsonb_build_object('parent_name', x.parent_name, 'body', x.body, 'created_at', x.created_at) order by x.created_at)
                   from public.flash_replies x where x.flash_id = f.id), '[]'::jsonb)
                 else coalesce((
                   select jsonb_agg(jsonb_build_object('parent_name', x.parent_name, 'body', x.body, 'created_at', x.created_at) order by x.created_at)
                   from public.flash_replies x where x.flash_id = f.id and x.parent_id = v_parent), '[]'::jsonb) end)
      order by f.created_at desc)
    from public.class_flashes f join public.classes c on c.id = f.class_id
    where f.expires_at > now()
      and (case when p_class_id is not null then f.class_id = p_class_id else public.parent_in_class(f.class_id) end)), '[]'::jsonb);
end;
$$;

create or replace function public.flash_react(p_flash_id uuid, p_reaction text)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_parent uuid := public.current_parent_id();
  v_class  uuid;
  v_on     boolean;
begin
  select class_id into v_class from public.class_flashes where id = p_flash_id and expires_at > now();
  if v_parent is null or v_class is null or not public.parent_in_class(v_class) then
    raise exception 'Không tìm thấy khoảnh khắc' using hint = 'NOT_FOUND';
  end if;
  if p_reaction not in ('HEART', 'PROUD') then
    raise exception 'Cảm xúc không hợp lệ' using hint = 'VALIDATION:reaction';
  end if;
  delete from public.flash_reactions where flash_id = p_flash_id and parent_id = v_parent and reaction = p_reaction;
  if not found then
    insert into public.flash_reactions (flash_id, parent_id, reaction) values (p_flash_id, v_parent, p_reaction);
    v_on := true;
  else
    v_on := false;
  end if;
  return jsonb_build_object('reaction', p_reaction, 'on', v_on);
end;
$$;

create or replace function public.flash_reply(p_flash_id uuid, p_body text)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_parent public.users;
  v_class  uuid;
begin
  select * into v_parent from public.users where id = public.current_parent_id();
  select class_id into v_class from public.class_flashes where id = p_flash_id and expires_at > now();
  if v_parent.id is null or v_class is null or not public.parent_in_class(v_class) then
    raise exception 'Không tìm thấy khoảnh khắc' using hint = 'NOT_FOUND';
  end if;
  if char_length(btrim(coalesce(p_body, ''))) not between 1 and 300 then
    raise exception 'Lời nhắn 1–300 ký tự' using hint = 'VALIDATION:body';
  end if;
  if (select count(*) from public.flash_replies where flash_id = p_flash_id and parent_id = v_parent.id) >= 5 then
    raise exception 'Tối đa 5 lời nhắn cho mỗi khoảnh khắc' using hint = 'RATE_LIMITED';
  end if;
  insert into public.flash_replies (flash_id, parent_id, parent_name, body) values (p_flash_id, v_parent.id, v_parent.full_name, btrim(p_body));
  return jsonb_build_object('ok', true);
end;
$$;

-- ─── Grants ─────────────────────────────────────────────────────────────────
revoke all on function public.ai_check_begin(uuid, text) from public, anon, authenticated;
revoke all on function public.ai_check_finish(uuid, boolean, jsonb, text) from public, anon, authenticated;
grant execute on function public.ai_check_begin(uuid, text) to service_role;
grant execute on function public.ai_check_finish(uuid, boolean, jsonb, text) to service_role;
do $$
declare f text;
begin
  foreach f in array array['public.flash_create(uuid, text, text, text, numeric)', 'public.flash_feed(uuid)',
                           'public.flash_react(uuid, text)', 'public.flash_reply(uuid, text)'] loop
    execute format('revoke all on function %s from public, anon', f);
    execute format('grant execute on function %s to authenticated', f);
  end loop;
end $$;

-- ───────────────── 20261128090000_voice_games_community.sql ─────────────────
-- ─────────────────────────────────────────────────────────────────────────────
-- Voice feedback on contact-book entries, mini-game points, private parent community.
--
--   daily_reports + voice_path / voice_duration   teacher's 15–30 s voice note (class-reports/class/<class_id>/…)
--                 + parent_clapped                 👏 reaction (❤️ is the existing parent_liked)
--   game_plays      60-second review games played by a child on the parent's phone → points (max 3 rewarded / day)
--   community_*     moderated feed for verified parents (child with an active / completed course) + staff.
--                   Staff comments carry the "Giáo viên giải đáp" badge. 3 reports hide a post until staff review.
-- ─────────────────────────────────────────────────────────────────────────────

-- ─── Voice feedback ─────────────────────────────────────────────────────────
alter table public.daily_reports
  add column if not exists voice_path text,
  add column if not exists voice_duration numeric(4, 1) check (voice_duration is null or voice_duration between 1 and 31),
  add column if not exists parent_clapped boolean not null default false;

-- Attach one voice note to the class's entries of a session (after daily_report_batch).
create or replace function public.daily_report_set_voice(p_class_id uuid, p_session_date date, p_student_ids uuid[], p_path text, p_duration numeric)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare v_n int;
begin
  if not coalesce(public.staff_owns_class(p_class_id), false) then
    raise exception 'Bạn không phụ trách lớp này' using hint = 'FORBIDDEN';
  end if;
  if public.storage_class_folder(p_path) is distinct from p_class_id then
    raise exception 'File ghi âm không thuộc lớp này' using hint = 'VALIDATION:voice';
  end if;
  if p_duration is null or p_duration < 1 or p_duration > 31 then
    raise exception 'Lời nhắn thoại dài 1–30 giây' using hint = 'VALIDATION:voice';
  end if;
  update public.daily_reports set voice_path = p_path, voice_duration = least(p_duration, 30)
   where class_id = p_class_id and session_date = p_session_date and student_id = any (coalesce(p_student_ids, '{}'));
  get diagnostics v_n = row_count;
  return jsonb_build_object('updated', v_n);
end;
$$;

create or replace function public.parent_report_clap(p_report_id uuid, p_on boolean)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare v_row public.daily_reports;
begin
  select * into v_row from public.daily_reports where id = p_report_id;
  if not found or not public.parent_can_see(v_row.student_id) then
    raise exception 'Không tìm thấy nhận xét' using hint = 'NOT_FOUND';
  end if;
  update public.daily_reports set parent_clapped = coalesce(p_on, false) where id = p_report_id;
  return jsonb_build_object('id', p_report_id, 'parent_clapped', coalesce(p_on, false));
end;
$$;

-- parent_reports now also returns the voice note and the 👏 reaction.
create or replace function public.parent_reports(p_student_id uuid, p_before date default null, p_limit int default 10)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  if not public.parent_can_see(p_student_id) and not public.staff_can_see_student(p_student_id) then
    raise exception 'Không có quyền xem sổ liên lạc của học viên này' using hint = 'FORBIDDEN';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', r.id, 'course_code', r.course_code, 'course_name', c.name, 'session_date', r.session_date,
      'attendance', r.attendance, 'teacher_name', r.teacher_name, 'feedback_text', r.feedback_text,
      'media_urls', r.media_urls, 'tags', r.tags, 'parent_liked', r.parent_liked, 'parent_clapped', r.parent_clapped,
      'parent_reply', r.parent_reply, 'voice_path', r.voice_path, 'voice_duration', r.voice_duration,
      'parent_replied_at', r.parent_replied_at, 'created_at', r.created_at) order by r.session_date desc, r.created_at desc)
    from (select * from public.daily_reports
           where student_id = p_student_id and (p_before is null or session_date < p_before)
           order by session_date desc, created_at desc
           limit least(greatest(coalesce(p_limit, 10), 1), 30)) r
    join public.categories c on c.code = r.course_code), '[]'::jsonb);
end;
$$;

-- ─── Mini-games ─────────────────────────────────────────────────────────────
create table public.game_plays (
  id          uuid primary key default gen_random_uuid(),
  student_id  uuid not null references public.students (id) on delete cascade,
  parent_id   uuid references public.users (id) on delete set null,
  game        text not null check (game in ('LETTER_HUNT', 'QUICK_MATH')),
  correct     smallint not null check (correct between 0 and 120),
  total       smallint not null check (total between 0 and 120 and correct <= total),
  points      smallint not null default 0 check (points between 0 and 100),
  played_on   date not null default (now() at time zone 'Asia/Ho_Chi_Minh')::date,
  created_at  timestamptz not null default now()
);
create index game_plays_student_idx on public.game_plays (student_id, played_on desc);
alter table public.game_plays enable row level security;
create policy "parents read their children's plays" on public.game_plays for select to authenticated
  using (public.parent_can_see(student_id) or public.staff_can_see_student(student_id));

-- Points: 1 per correct answer (max 30) + 10 bonus at ≥ 80 % (min 10 answers). Only the first 3 plays per child per
-- day earn points — the games are practice, not a grind. The score comes from the device, so it is capped by what
-- 60 seconds allow (≤ 60 answers).
create or replace function public.game_submit(p_student_id uuid, p_game text, p_correct int, p_total int)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_today  date := (now() at time zone 'Asia/Ho_Chi_Minh')::date;
  v_plays  int;
  v_points int := 0;
begin
  if not public.parent_can_see(p_student_id) then
    raise exception 'Không tìm thấy học viên' using hint = 'NOT_FOUND';
  end if;
  if p_game not in ('LETTER_HUNT', 'QUICK_MATH') then
    raise exception 'Trò chơi không hợp lệ' using hint = 'VALIDATION:game';
  end if;
  if p_total is null or p_correct is null or p_total < 0 or p_total > 60 or p_correct < 0 or p_correct > p_total then
    raise exception 'Kết quả không hợp lệ' using hint = 'VALIDATION:score';
  end if;
  select count(*) into v_plays from public.game_plays where student_id = p_student_id and played_on = v_today;
  if v_plays >= 30 then
    raise exception 'Hôm nay bé đã chơi nhiều rồi, nghỉ ngơi mai chơi tiếp nhé!' using hint = 'RATE_LIMITED';
  end if;
  if v_plays < 3 then
    v_points := least(p_correct, 30) + case when p_total >= 10 and p_correct * 5 >= p_total * 4 then 10 else 0 end;
  end if;
  insert into public.game_plays (student_id, parent_id, game, correct, total, points, played_on)
  values (p_student_id, public.current_parent_id(), p_game, p_correct, p_total, v_points, v_today);
  return jsonb_build_object(
    'points', v_points,
    'rewarded_left', greatest(0, 2 - v_plays),
    'total_points', (select coalesce(sum(points), 0) from public.game_plays where student_id = p_student_id));
end;
$$;

create or replace function public.game_summary(p_student_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare v_today date := (now() at time zone 'Asia/Ho_Chi_Minh')::date;
begin
  if not public.parent_can_see(p_student_id) and not public.staff_can_see_student(p_student_id) then
    raise exception 'Không tìm thấy học viên' using hint = 'NOT_FOUND';
  end if;
  return jsonb_build_object(
    'total_points', (select coalesce(sum(points), 0) from public.game_plays where student_id = p_student_id),
    'plays_today', (select count(*) from public.game_plays where student_id = p_student_id and played_on = v_today),
    'best', coalesce((select jsonb_object_agg(game, best) from (
               select game, max(correct) best from public.game_plays where student_id = p_student_id group by game) b), '{}'::jsonb));
end;
$$;

-- ─── Community ──────────────────────────────────────────────────────────────
create table public.community_posts (
  id             uuid primary key default gen_random_uuid(),
  author_user    uuid not null references auth.users (id) on delete cascade,
  author_parent  uuid references public.users (id) on delete set null,
  author_name    text not null,
  author_is_staff boolean not null default false,
  campus_location text references public.branches (code) on update cascade,
  kind           text not null check (kind in ('TIP', 'QUESTION', 'MILESTONE', 'BOOK_EXCHANGE')),
  body           text not null check (char_length(btrim(body)) between 5 and 2000),
  photo_path     text,
  status         text not null default 'VISIBLE' check (status in ('VISIBLE', 'HIDDEN')),
  hidden_reason  text check (hidden_reason is null or hidden_reason in ('REPORTED', 'STAFF', 'AUTHOR')),
  created_at     timestamptz not null default now()
);
create index community_posts_feed_idx on public.community_posts (status, created_at desc);

create table public.community_comments (
  id             uuid primary key default gen_random_uuid(),
  post_id        uuid not null references public.community_posts (id) on delete cascade,
  author_user    uuid not null references auth.users (id) on delete cascade,
  author_name    text not null,
  is_expert      boolean not null default false,
  body           text not null check (char_length(btrim(body)) between 1 and 1000),
  status         text not null default 'VISIBLE' check (status in ('VISIBLE', 'HIDDEN')),
  created_at     timestamptz not null default now()
);
create index community_comments_post_idx on public.community_comments (post_id, created_at);

create table public.community_likes (
  post_id     uuid not null references public.community_posts (id) on delete cascade,
  user_id     uuid not null references auth.users (id) on delete cascade,
  created_at  timestamptz not null default now(),
  primary key (post_id, user_id)
);

create table public.community_reports (
  id          uuid primary key default gen_random_uuid(),
  post_id     uuid references public.community_posts (id) on delete cascade,
  comment_id  uuid references public.community_comments (id) on delete cascade,
  reporter    uuid not null references auth.users (id) on delete cascade,
  reason      text check (reason is null or char_length(reason) <= 300),
  resolved    boolean not null default false,
  created_at  timestamptz not null default now(),
  check ((post_id is null) <> (comment_id is null))
);
create unique index community_reports_once on public.community_reports (reporter, coalesce(post_id, comment_id));

-- All access goes through the functions below (RLS on, no policies = no direct table access).
alter table public.community_posts enable row level security;
alter table public.community_comments enable row level security;
alter table public.community_likes enable row level security;
alter table public.community_reports enable row level security;

/** Staff, or a parent with a child who has (had) a course here. */
create or replace function public.community_member()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(public.is_staff(), false) or exists (
    select 1 from public.parent_student_links l join public.enrollments e on e.student_id = l.student_id
     where l.parent_id = public.current_parent_id() and e.status in ('ACTIVE', 'COMPLETED'));
$$;

create or replace function public.community_moderator()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(public.is_staff(), false) and coalesce(public.staff_kind() in ('ADMIN', 'MANAGER'), false);
$$;

create or replace function public.community_display_name()
returns text
language plpgsql
stable
security definer
set search_path = public, auth
as $$
begin
  return coalesce(
    (select full_name from public.users where id = public.current_parent_id()),
    (select coalesce(p.display_name, nullif(btrim(u.raw_user_meta_data ->> 'full_name'), ''), split_part(u.email, '@', 1))
       from auth.users u left join public.staff_profiles p on p.user_id = u.id where u.id = auth.uid()),
    'Thành viên');
end;
$$;

create or replace function public.community_feed(p_campus text default null, p_kind text default null, p_before timestamptz default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare v_mod boolean := public.community_moderator();
begin
  if not public.community_member() then
    raise exception 'Cộng đồng dành cho phụ huynh đang học tại TH EDU' using hint = 'FORBIDDEN';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', p.id, 'author_name', p.author_name, 'author_is_staff', p.author_is_staff, 'campus', p.campus_location,
      'kind', p.kind, 'body', p.body, 'photo_path', p.photo_path, 'status', p.status, 'hidden_reason', p.hidden_reason,
      'created_at', p.created_at, 'mine', p.author_user = auth.uid(),
      'likes', (select count(*) from public.community_likes l where l.post_id = p.id),
      'liked', exists (select 1 from public.community_likes l where l.post_id = p.id and l.user_id = auth.uid()),
      'comments', (select count(*) from public.community_comments c where c.post_id = p.id and c.status = 'VISIBLE'),
      'expert_answered', exists (select 1 from public.community_comments c where c.post_id = p.id and c.is_expert and c.status = 'VISIBLE'),
      'reports', case when v_mod then (select count(*) from public.community_reports r where r.post_id = p.id and not r.resolved) else 0 end
    ) order by p.created_at desc)
    from (select * from public.community_posts p
           where (p.status = 'VISIBLE' or v_mod or p.author_user = auth.uid())
             and (p_campus is null or p.campus_location = p_campus)
             and (p_kind is null or p.kind = p_kind)
             and (p_before is null or p.created_at < p_before)
           order by p.created_at desc limit 20) p), '[]'::jsonb);
end;
$$;

create or replace function public.community_post_create(p_kind text, p_body text, p_photo_path text default null)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_id uuid;
  v_campus text;
begin
  if not public.community_member() then
    raise exception 'Cộng đồng dành cho phụ huynh đang học tại TH EDU' using hint = 'FORBIDDEN';
  end if;
  if p_kind not in ('TIP', 'QUESTION', 'MILESTONE', 'BOOK_EXCHANGE') then
    raise exception 'Chọn loại bài viết' using hint = 'VALIDATION:kind';
  end if;
  if char_length(btrim(coalesce(p_body, ''))) not between 5 and 2000 then
    raise exception 'Nội dung 5–2000 ký tự' using hint = 'VALIDATION:body';
  end if;
  if p_photo_path is not null and split_part(p_photo_path, '/', 1) <> auth.uid()::text then
    raise exception 'Ảnh không hợp lệ' using hint = 'VALIDATION:photo';
  end if;
  if (select count(*) from public.community_posts where author_user = auth.uid() and created_at > now() - interval '1 day') >= 5 then
    raise exception 'Tối đa 5 bài viết mỗi ngày' using hint = 'RATE_LIMITED';
  end if;
  select s.campus_location into v_campus from public.parent_student_links l join public.students s on s.id = l.student_id
   where l.parent_id = public.current_parent_id() limit 1;
  if v_campus is null then v_campus := public.staff_campus(); end if;
  insert into public.community_posts (author_user, author_parent, author_name, author_is_staff, campus_location, kind, body, photo_path)
  values (auth.uid(), public.current_parent_id(), left(public.community_display_name(), 60), coalesce(public.is_staff(), false),
          v_campus, p_kind, btrim(p_body), p_photo_path)
  returning id into v_id;
  return jsonb_build_object('id', v_id);
end;
$$;

create or replace function public.community_comments_list(p_post_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare v_mod boolean := public.community_moderator();
begin
  if not public.community_member()
     or not exists (select 1 from public.community_posts where id = p_post_id and (status = 'VISIBLE' or v_mod or author_user = auth.uid())) then
    raise exception 'Không tìm thấy bài viết' using hint = 'NOT_FOUND';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('id', c.id, 'author_name', c.author_name, 'is_expert', c.is_expert, 'body', c.body,
                                        'status', c.status, 'mine', c.author_user = auth.uid(), 'created_at', c.created_at)
                     order by c.is_expert desc, c.created_at)
    from public.community_comments c where c.post_id = p_post_id and (c.status = 'VISIBLE' or v_mod)), '[]'::jsonb);
end;
$$;

create or replace function public.community_comment(p_post_id uuid, p_body text)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare v_id uuid;
begin
  if not public.community_member() or not exists (select 1 from public.community_posts where id = p_post_id and status = 'VISIBLE') then
    raise exception 'Không tìm thấy bài viết' using hint = 'NOT_FOUND';
  end if;
  if char_length(btrim(coalesce(p_body, ''))) not between 1 and 1000 then
    raise exception 'Bình luận 1–1000 ký tự' using hint = 'VALIDATION:body';
  end if;
  if (select count(*) from public.community_comments where author_user = auth.uid() and created_at > now() - interval '1 hour') >= 20 then
    raise exception 'Bạn bình luận hơi nhanh, nghỉ một chút nhé' using hint = 'RATE_LIMITED';
  end if;
  insert into public.community_comments (post_id, author_user, author_name, is_expert, body)
  values (p_post_id, auth.uid(), left(public.community_display_name(), 60), coalesce(public.is_staff(), false), btrim(p_body))
  returning id into v_id;
  return jsonb_build_object('id', v_id, 'is_expert', coalesce(public.is_staff(), false));
end;
$$;

create or replace function public.community_like(p_post_id uuid)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare v_on boolean;
begin
  if not public.community_member() or not exists (select 1 from public.community_posts where id = p_post_id and status = 'VISIBLE') then
    raise exception 'Không tìm thấy bài viết' using hint = 'NOT_FOUND';
  end if;
  delete from public.community_likes where post_id = p_post_id and user_id = auth.uid();
  v_on := not found;
  if v_on then insert into public.community_likes (post_id, user_id) values (p_post_id, auth.uid()); end if;
  return jsonb_build_object('on', v_on, 'likes', (select count(*) from public.community_likes where post_id = p_post_id));
end;
$$;

create or replace function public.community_report(p_post_id uuid default null, p_comment_id uuid default null, p_reason text default null)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare v_post uuid := p_post_id;
begin
  if not public.community_member() or (p_post_id is null) = (p_comment_id is null) then
    raise exception 'Không tìm thấy nội dung' using hint = 'NOT_FOUND';
  end if;
  if p_comment_id is not null then
    select post_id into v_post from public.community_comments where id = p_comment_id;
  end if;
  if v_post is null or not exists (select 1 from public.community_posts where id = v_post) then
    raise exception 'Không tìm thấy nội dung' using hint = 'NOT_FOUND';
  end if;
  insert into public.community_reports (post_id, comment_id, reporter, reason)
  values (p_post_id, p_comment_id, auth.uid(), left(nullif(btrim(coalesce(p_reason, '')), ''), 300))
  on conflict do nothing;
  -- 3 open reports hide the content until a moderator looks at it.
  if p_post_id is not null and (select count(*) from public.community_reports where post_id = p_post_id and not resolved) >= 3 then
    update public.community_posts set status = 'HIDDEN', hidden_reason = 'REPORTED' where id = p_post_id and status = 'VISIBLE';
  end if;
  if p_comment_id is not null and (select count(*) from public.community_reports where comment_id = p_comment_id and not resolved) >= 3 then
    update public.community_comments set status = 'HIDDEN' where id = p_comment_id;
  end if;
  return jsonb_build_object('ok', true);
end;
$$;

-- Moderators hide / restore; authors may hide (delete) their own post.
create or replace function public.community_moderate(p_post_id uuid default null, p_comment_id uuid default null, p_hidden boolean default true)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare v_mod boolean := public.community_moderator();
begin
  if p_post_id is not null then
    if not v_mod and not exists (select 1 from public.community_posts where id = p_post_id and author_user = auth.uid()) then
      raise exception 'Chỉ quản trị viên được kiểm duyệt' using hint = 'FORBIDDEN';
    end if;
    if not v_mod and not p_hidden then
      raise exception 'Chỉ quản trị viên được khôi phục bài' using hint = 'FORBIDDEN';
    end if;
    update public.community_posts
       set status = case when p_hidden then 'HIDDEN' else 'VISIBLE' end,
           hidden_reason = case when not p_hidden then null when v_mod then 'STAFF' else 'AUTHOR' end
     where id = p_post_id;
    if v_mod then update public.community_reports set resolved = true where post_id = p_post_id; end if;
  elsif p_comment_id is not null then
    if not v_mod and not exists (select 1 from public.community_comments where id = p_comment_id and author_user = auth.uid() and p_hidden) then
      raise exception 'Chỉ quản trị viên được kiểm duyệt' using hint = 'FORBIDDEN';
    end if;
    update public.community_comments set status = case when p_hidden then 'HIDDEN' else 'VISIBLE' end where id = p_comment_id;
    if v_mod then update public.community_reports set resolved = true where comment_id = p_comment_id; end if;
  else
    raise exception 'Không tìm thấy nội dung' using hint = 'NOT_FOUND';
  end if;
  return jsonb_build_object('ok', true);
end;
$$;

-- Community photos: private bucket, each member uploads into their own folder <auth uid>/…, members read.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('community', 'community', false, 5242880, array['image/jpeg', 'image/png', 'image/webp'])
on conflict (id) do update set public = false, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;

drop policy if exists "community members upload own photos" on storage.objects;
create policy "community members upload own photos" on storage.objects for insert to authenticated
  with check (bucket_id = 'community' and split_part(name, '/', 1) = auth.uid()::text and public.community_member());
drop policy if exists "community members read photos" on storage.objects;
create policy "community members read photos" on storage.objects for select to authenticated
  using (bucket_id = 'community' and public.community_member());

-- ─── Grants ─────────────────────────────────────────────────────────────────
do $$
declare f text;
begin
  foreach f in array array[
    'public.daily_report_set_voice(uuid, date, uuid[], text, numeric)', 'public.parent_report_clap(uuid, boolean)',
    'public.parent_reports(uuid, date, int)',
    'public.game_submit(uuid, text, int, int)', 'public.game_summary(uuid)',
    'public.community_member()', 'public.community_moderator()', 'public.community_display_name()',
    'public.community_feed(text, text, timestamptz)', 'public.community_post_create(text, text, text)',
    'public.community_comments_list(uuid)', 'public.community_comment(uuid, text)', 'public.community_like(uuid)',
    'public.community_report(uuid, uuid, text)', 'public.community_moderate(uuid, uuid, boolean)'
  ] loop
    execute format('revoke all on function %s from public, anon', f);
    execute format('grant execute on function %s to authenticated', f);
  end loop;
end $$;

-- ───────────────── 20261129090000_app_release_config.sql ─────────────────
-- ═══════════════════════════════════════════════════════════════════════════
-- App release config: store version gate (soft "nên cập nhật" / force "bắt buộc cập nhật").
-- One row per platform. Read by everyone (anon included — the check runs before sign-in),
-- edited only by admins in the Supabase Table Editor (or SQL).
--
--   min_supported_version : installed version BELOW this → blocking "Bắt buộc cập nhật" screen
--   latest_version        : installed version below this → dismissible "Đã có phiên bản mới" card
--   is_force_update       : true → treat ANY version below latest_version as forced (hotfix)
--   store_url             : Google Play / App Store link opened by the buttons
--   release_notes_vi      : short Vietnamese highlights shown to parents / teachers
--
-- Safe defaults: min 0.0.0 (never blocks), latest = current version. Empty store_url → the
-- prompts are not shown (nothing to open).
-- ═══════════════════════════════════════════════════════════════════════════

create table if not exists public.app_release_config (
  platform text primary key check (platform in ('android', 'ios')),
  min_supported_version text not null default '0.0.0' check (min_supported_version ~ '^\d{1,6}(\.\d{1,6}){0,2}$'),
  latest_version text not null default '0.0.0' check (latest_version ~ '^\d{1,6}(\.\d{1,6}){0,2}$'),
  store_url text not null default '' check (store_url = '' or store_url ~* '^https://'),
  release_notes_vi text not null default '' check (char_length(release_notes_vi) <= 600),
  is_force_update boolean not null default false,
  updated_at timestamptz not null default now()
);

comment on table public.app_release_config is 'Store version gate for the mobile apps (soft / force update). Public read, admin write.';

create or replace function public.app_release_config_touch() returns trigger
language plpgsql as $$
begin
  new.updated_at := now();
  return new;
end $$;

drop trigger if exists app_release_config_touch on public.app_release_config;
create trigger app_release_config_touch before update on public.app_release_config
  for each row execute function public.app_release_config_touch();

alter table public.app_release_config enable row level security;

drop policy if exists app_release_config_read on public.app_release_config;
create policy app_release_config_read on public.app_release_config for select to anon, authenticated using (true);

-- No insert / update / delete policies: only the dashboard (service role) or SQL can change it.
revoke insert, update, delete on public.app_release_config from anon, authenticated;
grant select on public.app_release_config to anon, authenticated;

insert into public.app_release_config (platform, min_supported_version, latest_version, store_url, release_notes_vi)
values
  ('android', '0.0.0', '0.1.0', '', ''),
  ('ios', '0.0.0', '0.1.0', '', '')
on conflict (platform) do nothing;

